function update(rel,anchor,block){const p=path.join(ROOT,rel);let s=fs.readFileSync(p,'utf8');if(s.includes(MARK))return false;if(!s.includes(anchor))throw new Error(`Ancre introuvable dans ${rel}`);s=s.replace(anchor,block+anchor);fs.writeFileSync(p,s,'utf8');return true;}

const savings=`<!-- ${MARK} -->\n<div class="case-study" id="reperes-2026"><h2>Repères chiffrés — août 2026</h2><p><strong>Données observées, France, vérifiées le 9 août 2026.</strong> À compter du 1er août 2026, le Livret A et le LDDS rémunèrent 1,7 % par an, le LEP 2,5 % pour les personnes éligibles. Le plafond de versements du Livret A est de 22 950 € et celui du LEP de 10 000 €. Un PEL ouvert depuis le 1er janvier 2026 rémunère 2 % brut ; son taux est fixé à l'ouverture et un retrait avant quatre ans entraîne en principe la clôture du plan.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Support</th><th>Taux / repère</th><th>Sur 10 000 € pendant 1 an</th><th>Point décisif</th></tr></thead><tbody><tr><td>Livret A / LDDS</td><td>1,7 % net d'impôt</td><td><strong>170 €</strong></td><td>Disponible, taux révisable.</td></tr><tr><td>LEP</td><td>2,5 % net d'impôt</td><td><strong>250 €</strong></td><td>Réservé aux personnes éligibles ; plafond 10 000 €.</td></tr><tr><td>PEL ouvert en 2026</td><td>2 % brut</td><td><strong>200 € brut</strong>, soit env. 140 € avec PFU de 30 %</td><td>Taux contractuel, mais liquidité et fiscalité différentes.</td></tr></tbody></table></div><p><strong>Ce que montre le calcul :</strong> sur 10 000 €, l'écart entre 1,7 % et 2,5 % représente 80 € sur un an. C'est utile à connaître, mais insuffisant pour choisir : le LEP n'est pas accessible à tous et le PEL ne rend pas le même service qu'un livret disponible à tout moment.</p><p class="source-note">Sources : Ministère de l'Économie, 15 juillet 2026 — <a href="https://presse.economie.gouv.fr/epargne-reglementee-le-livret-a-passe-a-17-et-le-lep-se-maintient-a-25-a-compter-du-1er-aout-2026/" rel="noopener noreferrer">Livret A / LEP</a> ; <a href="https://www.economie.gouv.fr/particuliers/gerer-mon-argent/gerer-mon-budget-et-mon-epargne/plan-epargne-logement-pel-comment-ca-marche" rel="noopener noreferrer">PEL</a>.</p></div>\n`;
update('articles/comparatif-produits-bancaires.html','<h2>1. Commencer par la date où l’argent peut être nécessaire</h2>',savings);

const credit=`<!-- ${MARK} -->\n<div class="case-study" id="reperes-credit-2026"><h2>Repères chiffrés — crédit en France, mai 2026</h2><p><strong>Données observées publiées par la Banque de France.</strong> En mai 2026, le taux moyen des nouveaux crédits à l'habitat hors renégociations est de <strong>3,21 %</strong>, hors frais et assurance. Le taux moyen des prêts amortissables à la consommation est de <strong>6,53 %</strong>. Ces taux sont des moyennes de flux, pas des TAEG proposés à chaque emprunteur.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Exemple pédagogique</th><th>Mensualité hors assurance</th><th>Intérêts sur la durée</th><th>Total remboursé</th></tr></thead><tbody><tr><td>200 000 € à 3,21 % sur 20 ans</td><td><strong>≈ 1 130 €</strong></td><td>≈ 71 300 €</td><td>≈ 271 300 €</td></tr><tr><td>200 000 € à 3,21 % sur 25 ans</td><td><strong>≈ 970 €</strong></td><td>≈ 91 100 €</td><td>≈ 291 100 €</td></tr><tr><td>20 000 € à 6,53 % sur 5 ans</td><td><strong>≈ 392 €</strong></td><td>≈ 3 500 €</td><td>≈ 23 500 €</td></tr></tbody></table></div><p><strong>Le piège de la mensualité :</strong> dans l'exemple immobilier, passer de 20 à 25 ans réduit la mensualité d'environ 160 €, mais ajoute près de <strong>19 800 € d'intérêts</strong>. Le calcul n'inclut ni assurance, ni frais, ni garantie : le TAEG réel sera donc différent.</p><p class="source-note">Source : <a href="https://www.banque-france.fr/fr/statistiques/credit/credits-aux-particuliers-2026-05" rel="noopener noreferrer">Banque de France — Crédits aux particuliers, mai 2026</a>, mise en ligne le 8 juillet 2026.</p></div>\n`;
update('dossiers/finances-credit-endettement.html','<h2>1. Commencer par la fonction de la dette</h2>',credit);

const allocation=`<!-- ${MARK} -->\n<div class="case-study" id="reperes-risque-msci"><h2>Un repère historique concret : le MSCI World a déjà perdu 57,82 %</h2><p><strong>Donnée observée, pas scénario inventé.</strong> Au 30 juin 2026, MSCI indique pour son indice World une volatilité annualisée de <strong>14,89 % sur dix ans</strong> et un drawdown historique maximal de <strong>57,82 %</strong>, entre le 31 octobre 2007 et le 9 mars 2009. L'indice comptait alors 1 283 grandes et moyennes capitalisations des marchés développés.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Si 100 000 € subissent...</th><th>Capital après baisse</th><th>Hausse nécessaire pour revenir à 100 000 €</th></tr></thead><tbody><tr><td>-20 %</td><td>80 000 €</td><td>+25 %</td></tr><tr><td>-40 %</td><td>60 000 €</td><td>+66,7 %</td></tr><tr><td>-57,82 %</td><td>42 180 €</td><td><strong>≈ +137,1 %</strong></td></tr></tbody></table></div><p>Un indice mondial diversifié réduit le risque spécifique à une entreprise ; il ne supprime pas le risque actions. C'est précisément pour cela que la part d'actions doit dépendre de l'horizon, de la liquidité nécessaire et de la capacité à ne pas vendre pendant une crise.</p><p class="source-note">Source : <a href="https://www.msci.com/indexes/index/990100/msci-world-index" rel="noopener noreferrer">MSCI — MSCI World Index</a>, données au 30 juin 2026.</p></div>\n`;
update('dossiers/finances-allocation-portefeuille.html','<div class="dossier-section" id="diversification">',allocation);

